/* destaque de valores + pix, logo no topo */
.destaque{position:relative;margin-top:38px;padding:clamp(26px,3.8vw,34px) clamp(18px,3.2vw,30px) clamp(20px,3vw,28px);
  border:2px solid rgba(232,123,35,.42);border-radius:16px;
  background:linear-gradient(180deg,rgba(255,255,255,.8),rgba(232,123,35,.1));
  box-shadow:0 20px 42px -30px rgba(30,42,58,.9)}
.destaque::before{content:'';position:absolute;top:-11px;left:50%;width:112px;height:22px;background:var(--fita);
  transform:translateX(-50%) rotate(-1.4deg);box-shadow:0 1px 3px rgba(0,0,0,.16)}
.destaque .selo{position:absolute;top:-14px;left:clamp(14px,4vw,26px);
  font-weight:800;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:#fff;
  background:var(--laranja);border-radius:999px;padding:6px 15px;box-shadow:0 8px 16px -9px rgba(232,123,35,.95)}
.destaque h2{margin:4px 0 0;font-weight:800;font-size:clamp(22px,4.2vw,32px);color:var(--azul-marca);letter-spacing:-.02em}

.precos{display:grid;grid-template-columns:repeat(auto-fit,minmax(196px,1fr));gap:14px;margin-top:20px}
