.preco-card .nome{font-weight:600;font-size:15px;line-height:1.3}
.preco-card .valor{font-weight:800;font-size:clamp(31px,6.2vw,40px);color:var(--laranja);letter-spacing:-.03em;margin-top:8px;line-height:1}
