.pix-topo .banco{font-weight:700;font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:#fff;
  background:#820AD1;border-radius:999px;padding:6px 13px}
.pix .rotulo{margin-top:14px}
.pix-chave{display:flex;flex-wrap:wrap;align-items:stretch;gap:10px}
.pix-chave code{flex:1 1 260px;min-width:0;display:flex;align-items:center;background:#FFFCF6;
