  font:600 14px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--tinta);
  letter-spacing:.01em;overflow-wrap:anywhere}
.copiar{flex:none;cursor:pointer;border:none;border-radius:10px;padding:12px 22px;
  font:700 14.5px 'Montserrat',sans-serif;color:#fff;background:var(--azul-marca);
  box-shadow:0 10px 22px -13px rgba(27,78,155,.95);transition:transform .14s,filter .14s,background .14s}
.copiar:hover{transform:translateY(-2px);filter:brightness(1.07)}
.copiar.feito{background:#1E7A45}
.pix-dados{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-top:15px}
.pix-dados .rot{font-weight:700;font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--tinta-fraca)}
.pix-dados .val{font-weight:700;font-size:15.5px;color:var(--azul-marca);margin-top:3px;line-height:1.3}

